const fs=require('node:fs'),cp=require('node:child_process');
const before=fs.readFileSync('backup-manifest.json','utf8');
cp.execSync('node backup.js',{stdio:'inherit'});
const after=fs.readFileSync('backup-manifest.json','utf8');
console.log('IDEMPOTENT (re-run identical):', before===after);
const j=JSON.parse(after);
console.log('valid JSON, files =',JSON.stringify(j.files));
console.log('manifest self-excluded:', !j.files.includes('backup-manifest.json'));
console.log('no hidden entries:', !j.files.some(f=>f.split('/').some(s=>s.startsWith('.'))));
console.log('sorted:', JSON.stringify(j.files)===JSON.stringify([...j.files].sort()));
console.log('matches dir listing:', JSON.stringify(j.files)===JSON.stringify(fs.readdirSync('.').filter(n=>!n.startsWith('.')&&fs.lstatSync(n).isFile()&&n!=='backup-manifest.json').sort()));
"

